const listeners = new Set<() => void>();

function safeStorage(): LanguageStorage | null {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function isAppLanguage(value: unknown): value is AppLanguage {
  return value === "en" || value === "es";
}

export function readStoredLanguage(storage: LanguageStorage | null = safeStorage()): AppLanguage {
  if (!storage) return "en";

  try {
    const stored = storage.getItem(LANGUAGE_STORAGE_KEY);
    return isAppLanguage(stored) ? stored : "en";
  } catch {
    return "en";
  }
}

export function writeStoredLanguage(language: AppLanguage, storage: LanguageStorage | null = safeStorage()) {
  if (!storage) return;

  try {
    storage.setItem(LANGUAGE_STORAGE_KEY, language);
  } catch {
    // Browser storage can be unavailable in private mode; keep the UI usable.
  }
}

function interpolate(template: string, values?: TranslationValues) {
  if (!values) return template;

  return template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
    const value = values[key];
    return value === undefined || value === null ? match : String(value);
  });
}

export function translate(key: string, language: AppLanguage = "en", values?: TranslationValues) {
  const template = translations[language][key] ?? translations.en[key] ?? key;
  return interpolate(template, values);
}

function getLanguageSnapshot() {
  return readStoredLanguage();
}

function getServerLanguageSnapshot(): AppLanguage {
  return "en";
}

function subscribeLanguage(listener: () => void) {
  listeners.add(listener);

  if (typeof window === "undefined") {
    return () => {
      listeners.delete(listener);
    };
  }

  const handleStorage = (event: StorageEvent) => {
    if (event.key === LANGUAGE_STORAGE_KEY) {
      listener();
    }
  };

  window.addEventListener("storage", handleStorage);

  return () => {
    listeners.delete(listener);
    window.removeEventListener("storage", handleStorage);
  };
}

function notifyLanguageListeners() {
  listeners.forEach((listener) => listener());
}

export function setStoredLanguage(language: AppLanguage, storage: LanguageStorage | null = safeStorage()) {
  writeStoredLanguage(language, storage);
  notifyLanguageListeners();
}

export function useLanguage() {
  const language = useSyncExternalStore(
    subscribeLanguage,
    getLanguageSnapshot,
    getServerLanguageSnapshot,
  );

  const setLanguage = useCallback((nextLanguage: AppLanguage) => {
    setStoredLanguage(nextLanguage);
  }, []);

  const t = useCallback(
    (key: string, values?: TranslationValues) => translate(key, language, values),
    [language],
  );

  return {
    language,
    setLanguage,
    t,
  };
}

export function localeForLanguage(language: AppLanguage) {
  return language === "es" ? "es-US" : "en-US";
}

export function formatLocalizedDate(value: Date | string | number, language: AppLanguage, options: Intl.DateTimeFormatOptions = {}) {
  return new Intl.DateTimeFormat(localeForLanguage(language), options).format(new Date(value));
}

export function formatLocalizedCurrency(value: number, language: AppLanguage) {
  return new Intl.NumberFormat(localeForLanguage(language), { style: "currency", currency: "USD" }).format(value);
}

export function translateMaterialCatalogLabel(
  material: { slug?: string | null; displayName?: string | null } | null | undefined,
  t: (key: string) => string,
) {
  if (!material) return "";
  const slug = material.slug?.trim();
  if (!slug) return material.displayName || "";
  const key = `material.catalog.${slug}`;
  const translated = t(key);
  return translated === key ? material.displayName || slug : translated;
}

export function translateMaterialCatalogCategory(category: string | null | undefined, t: (key: string) => string) {
  if (!category) return "";
  const slug = category.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  const key = `material.category.${slug}`;
  const translated = t(key);
  return translated === key ? category : translated;
}

export function translateActivityStatus(status: string | null | undefined, t: (key: string) => string) {
  const normalized = (status || "").toLowerCase();
  if (["verified", "approved", "completed"].includes(normalized)) return t("common.verified");
  if (["rejected", "declined", "cancelled", "canceled"].includes(normalized)) return t("common.rejected");
  return t("common.pending");
}
